let canvas=$("#card-canvas"),ctx=canvas.getContext("2d");
const state={art:null,artIsProjectAsset:false,artZoom:1,artX:0,artY:0,setLogos:new Map(),pointerMap:new Map(),dragPointerId:null,dragLast:null,lastPinchDistance:null,activeLayoutKey:"card",renderPlateOnly:false,layouts:{card:{zoom:1,x:0,y:0},headshot:{zoom:1,x:0,y:0}}};
const BUILD_VERSION="0.13.72";
function assetUrl(path){
  const url=new URL(`../${path}`,document.location.href);
  if(url.protocol==="http:"||url.protocol==="https:") url.searchParams.set("v",BUILD_VERSION);
  return url.href;
}
function loadImage(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error("Image could not be loaded"));im.src=src;});}
function readFileAsDataUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error||new Error("File could not be read"));reader.readAsDataURL(file);});}
function scale(){return canvas.width/680;}
function layoutKey(){return isHeadshotMode()?"headshot":"card";}
function referenceSize(){return isHeadshotMode()?{w:1200,h:400}:{w:680,h:1000};}
function layoutLimits(){return isHeadshotMode()?{x:2400,y:2400,zoomMin:.15,zoomMax:5}:{x:260,y:320,zoomMin:.45,zoomMax:3.2};}
function syncLayoutControls(){const limits=layoutLimits(),xRange=isHeadshotMode()?Math.max(limits.x,Math.ceil(Math.abs(state.artX)/100)*100):limits.x,yRange=isHeadshotMode()?Math.max(limits.y,Math.ceil(Math.abs(state.artY)/100)*100):limits.y,zoom=$("#art-zoom"),x=$("#art-x"),y=$("#art-y");zoom.min=Math.round(limits.zoomMin*100);zoom.max=Math.round(limits.zoomMax*100);x.min=-xRange;x.max=xRange;y.min=-yRange;y.max=yRange;zoom.value=Math.round(state.artZoom*100);x.value=Math.round(state.artX);y.value=Math.round(state.artY);}
function saveLayout(key=state.activeLayoutKey||layoutKey()){state.layouts[key]={zoom:state.artZoom,x:state.artX,y:state.artY};}
function restoreLayout(key=layoutKey()){const saved=state.layouts[key]||{zoom:1,x:0,y:0},limits=layoutLimits();state.activeLayoutKey=key;state.artZoom=Math.max(limits.zoomMin,Math.min(limits.zoomMax,saved.zoom));state.artX=saved.x;state.artY=saved.y;if(!isHeadshotMode()){state.artX=Math.max(-limits.x,Math.min(limits.x,state.artX));state.artY=Math.max(-limits.y,Math.min(limits.y,state.artY));}syncLayoutControls();updateOutputs();}
function currentCard(){const id=$("#card-select").value;return STUDIO_CARDS.find(c=>c.id===id)||null;}
function currentSet(){const card=currentCard();return SETS[card?.setId]||SETS[$("#set-select").value]||SETS["summerslam-series-1"];}
function exportId(card){return card?.kind==="superstar"?(card.superstarId||card.id.replace(/^superstar-/,"")):card?.artKey||card?.id;}
function isHeadshotMode(){return $("#export-target")?.value==="headshot";}
function isLayeredFormat(){const card=currentCard();return !isHeadshotMode() && card?.kind!=="momentum" && $("#front-format")?.value==="layered";}
function previewPlateOnly(){return isLayeredFormat() && $("#preview-mode")?.value==="plate";}
function destinationFor(card){if(!card)return "assets/cards/art/custom/…";if(isHeadshotMode())return `assets/cards/art/custom/headshots/${exportId(card)}.webp`;const root=isLayeredFormat()?"assets/cards/art/layered":"assets/cards/art/custom";return `${root}/${KIND_FOLDERS[card.kind]||"cards"}/${exportId(card)}.webp`;}
function status(text,ok=null){const el=$("#status");if(!el)return;el.textContent=text||"";el.className=`status${ok===true?" ok":ok===false?" error":""}`;}
function urlStatus(text,ok=null){const el=$("#url-status");if(!el)return;el.textContent=text||"";el.className=`url-status${ok===true?" ok":ok===false?" error":""}`;}
function resetCanvasSurface(){const fresh=canvas.cloneNode(false);fresh.width=canvas.width;fresh.height=canvas.height;canvas.replaceWith(fresh);canvas=fresh;ctx=canvas.getContext("2d");wireCanvasEvents();}
function canvasIsOriginClean(){try{ctx.getImageData(0,0,1,1);return true;}catch{return false;}}
function roundedRect(c,x,y,w,h,r){ c.beginPath();c.roundRect(x,y,w,h,r); }
function frame(c,w,h,a,b){const s=scale();c.save();roundedRect(c,9*s,9*s,w-18*s,h-18*s,27*s);c.strokeStyle=a;c.lineWidth=9*s;c.shadowColor="rgba(0,0,0,.72)";c.shadowBlur=8*s;c.stroke();c.shadowColor="transparent";roundedRect(c,22*s,22*s,w-44*s,h-44*s,21*s);c.strokeStyle=b||"rgba(255,255,255,.58)";c.globalAlpha=.78;c.lineWidth=2*s;c.stroke();c.globalAlpha=.38;roundedRect(c,28*s,28*s,w-56*s,h-56*s,18*s);c.strokeStyle="#ffffff";c.lineWidth=.8*s;c.stroke();c.restore();}
