function drawRaw(c,w,h){ const g=c.createLinearGradient(0,0,w,h);g.addColorStop(0,"#030304");g.addColorStop(.38,"#0d0d10");g.addColorStop(.72,"#31070c");g.addColorStop(1,"#980d1b");c.fillStyle=g;c.fillRect(0,0,w,h);const glow=c.createRadialGradient(w*.72,h*.18,0,w*.72,h*.18,w*.6);glow.addColorStop(0,"rgba(239,38,55,.38)");glow.addColorStop(.38,"rgba(122,10,22,.16)");glow.addColorStop(1,"rgba(0,0,0,0)");c.fillStyle=glow;c.fillRect(0,0,w,h);c.save();c.globalAlpha=.26;c.strokeStyle="#ef2637";c.lineWidth=4*scale();for(let i=-5;i<14;i++){c.beginPath();c.moveTo(-w*.18,h*(.10+i*.105));c.lineTo(w*1.15,h*(-.08+i*.105));c.stroke();}c.globalAlpha=.10;c.strokeStyle="#d7dbe0";c.lineWidth=2*scale();for(let i=-3;i<10;i++){c.beginPath();c.moveTo(w*(i*.14-.18),0);c.lineTo(w*(i*.14+.20),h);c.stroke();}c.restore();}
