function isDanhausenHalloweenCard(){const card=currentCard();return !!card&&(card.superstarId==="danhausen"||["danhausen-very-nice-knee-vil","danhausen-triple-d","entrance-danhausen","special-danhausen","superstar-danhausen"].includes(card.id));}
function drawNewGeneration(c,w,h){
  const s=scale(),g=c.createLinearGradient(0,0,w,h);
  g.addColorStop(0,"#090d34");g.addColorStop(.34,"#25256f");g.addColorStop(.66,"#57246f");g.addColorStop(1,"#11123b");c.fillStyle=g;c.fillRect(0,0,w,h);
  const magenta=c.createRadialGradient(w*.73,h*.16,0,w*.73,h*.16,w*.68);magenta.addColorStop(0,"rgba(238,59,159,.38)");magenta.addColorStop(.38,"rgba(118,49,158,.18)");magenta.addColorStop(1,"rgba(0,0,0,0)");c.fillStyle=magenta;c.fillRect(0,0,w,h);
  const cyan=c.createRadialGradient(w*.16,h*.72,0,w*.16,h*.72,w*.58);cyan.addColorStop(0,"rgba(49,224,212,.24)");cyan.addColorStop(.48,"rgba(49,224,212,.08)");cyan.addColorStop(1,"rgba(0,0,0,0)");c.fillStyle=cyan;c.fillRect(0,0,w,h);
  c.save();
  c.globalAlpha=.22;c.lineWidth=4*s;
  for(let i=-5;i<15;i++){c.strokeStyle=i%2?"#31e0d4":"#ee3b9f";c.beginPath();c.moveTo(-w*.22,h*(.10+i*.105));c.lineTo(w*1.18,h*(-.08+i*.105));c.stroke();}
  c.globalAlpha=.16;c.strokeStyle="#ffdc00";c.lineWidth=2*s;
  for(let x=-w*.35;x<w*1.25;x+=w*.13){c.beginPath();c.moveTo(x,h*.72);c.lineTo(x+w*.20,h);c.stroke();}
  c.globalAlpha=.25;c.fillStyle="#31e0d4";
  for(let i=0;i<7;i++){const x=w*(.06+i*.145),y=h*(.09+(i%3)*.075),r=4.2*s;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fill();}
  c.fillStyle="#ee3b9f";
  for(let i=0;i<5;i++){const x=w*(.08+i*.19),y=h*(.82+(i%2)*.055),z=9*s;c.save();c.translate(x,y);c.rotate((i%2?1:-1)*Math.PI/4);c.fillRect(-z/2,-z/2,z,z);c.restore();}
  c.globalAlpha=.20;c.strokeStyle="#fff6a8";c.lineWidth=2*s;
  c.beginPath();c.moveTo(w*.05,h*.31);c.bezierCurveTo(w*.14,h*.25,w*.19,h*.39,w*.28,h*.33);c.bezierCurveTo(w*.37,h*.27,w*.42,h*.40,w*.51,h*.34);c.stroke();
  c.restore();
}
function drawSurvivorSeries(c,w,h){const g=c.createLinearGradient(0,0,w,h);g.addColorStop(0,"#06162f");g.addColorStop(.52,"#0a1c36");g.addColorStop(1,"#020812");c.fillStyle=g;c.fillRect(0,0,w,h);const orange=c.createRadialGradient(w*.78,h*.18,0,w*.78,h*.18,w*.72);orange.addColorStop(0,"rgba(255,107,27,.38)");orange.addColorStop(.42,"rgba(212,73,12,.11)");orange.addColorStop(1,"rgba(0,0,0,0)");c.fillStyle=orange;c.fillRect(0,0,w,h);c.save();c.globalAlpha=.16;c.strokeStyle="#9aa5b5";c.lineWidth=2*scale();const gap=w*.105;for(let x=-w;x<w*2;x+=gap){c.beginPath();c.moveTo(x,0);c.lineTo(x+h*.72,h);c.stroke();c.beginPath();c.moveTo(x+h*.72,0);c.lineTo(x,h);c.stroke();}c.globalAlpha=.34;c.strokeStyle="#ff6b1b";c.lineWidth=4*scale();for(let i=-2;i<10;i++){c.beginPath();c.moveTo(-w*.10,h*(.12+i*.14));c.lineTo(w*1.10,h*(-.02+i*.14));c.stroke();}c.globalAlpha=.28;c.strokeStyle="#e4e9ef";c.lineWidth=2*scale();c.strokeRect(w*.035,h*.025,w*.93,h*.95);c.restore();}
