function drawTemplate(){const w=canvas.width,h=canvas.height,set=currentCard()?.setId||$("#set-select").value;if(set==="survivor-series-series-1")drawSurvivorSeries(ctx,w,h);else if(set==="smackdown-series-1")drawSmackDown(ctx,w,h);else if(set==="money-in-the-bank-series-1")drawMoneyInTheBank(ctx,w,h);else if(set==="worlds-collide-series-1")drawWorldsCollide(ctx,w,h);else if(set==="raw-series-1")drawRaw(ctx,w,h);else if(set==="new-generation-series-1")drawNewGeneration(ctx,w,h);else if(set==="hall-of-fame-series-1")drawHall(ctx,w,h);else if(set==="evolution-series-1")drawEvolution(ctx,w,h);else if(set==="season-1-final-boss"||set==="season-2-whos-next")drawRewards(ctx,w,h);else drawSummerSlam(ctx,w,h);}
function drawArt(){if(!state.art)return;const w=canvas.width,h=canvas.height,im=state.art,ref=referenceSize(),iw=im.naturalWidth||im.width,ih=im.naturalHeight||im.height;const base=Math.max(w/iw,h/ih),k=base*state.artZoom,dw=iw*k,dh=ih*k,x=(w-dw)/2+state.artX*(w/ref.w),y=(h-dh)/2+state.artY*(h/ref.h);ctx.drawImage(im,x,y,dw,dh);}
