const CARD_FONT_DISPLAY = '900 1px "Bahnschrift Condensed", "Avenir Next Condensed", "Arial Narrow", "Helvetica Neue", Arial, sans-serif';
const CARD_FONT_META = '700 1px "Bahnschrift SemiCondensed", "Avenir Next", "Segoe UI", "Helvetica Neue", Arial, sans-serif';
const CARD_FONT_NUMBER = '800 1px "DIN Alternate", "Bahnschrift SemiCondensed", "Avenir Next Condensed", "Arial Narrow", Arial, sans-serif';
function cardFont(stack,size,weight){return `${weight} ${size*scale()}px ${stack}`;}
const DISPLAY_STACK='"Bahnschrift Condensed", "Avenir Next Condensed", "Arial Narrow", "Helvetica Neue", Arial, sans-serif';
const META_STACK='"Bahnschrift SemiCondensed", "Avenir Next", "Segoe UI", "Helvetica Neue", Arial, sans-serif';
const NUMBER_STACK='"DIN Alternate", "Bahnschrift SemiCondensed", "Avenir Next Condensed", "Arial Narrow", Arial, sans-serif';
function trackedWidth(text,tracking){const chars=[...String(text)];return chars.reduce((n,ch)=>n+ctx.measureText(ch).width,0)+Math.max(0,chars.length-1)*tracking;}
function drawTrackedText(text,x,y,tracking,{stroke=false}={}){const chars=[...String(text)],total=trackedWidth(text,tracking);let cursor=x-total/2;for(const ch of chars){const cw=ctx.measureText(ch).width;if(stroke)ctx.strokeText(ch,cursor+cw/2,y);else ctx.fillText(ch,cursor+cw/2,y);cursor+=cw+tracking;}}
const MOMENTUM_STUDIO_META={strength:{color:"#ff8a1f",light:"#ffd29e",short:"ST"},strike:{color:"#ef3f4e",light:"#ffc0c5",short:"SR"},technical:{color:"#36c86f",light:"#bdf5cf",short:"TE"},agility:{color:"#2fa8ff",light:"#bfe7ff",short:"AG"}};
function drawMomentumGlyph(method,cx,cy,r){ctx.save();ctx.translate(cx,cy);ctx.strokeStyle=MOMENTUM_STUDIO_META[method]?.light||"#fff";ctx.fillStyle="transparent";ctx.lineWidth=Math.max(3,5*scale());ctx.lineCap="round";ctx.lineJoin="round";if(method==="strength"){[-.48,-.2,.08,.36].forEach((y,i)=>{ctx.beginPath();ctx.moveTo(-r*(.58-i*.1),r*y);ctx.lineTo(r*(.58-i*.1),r*y);ctx.stroke();});}else if(method==="strike"){const pts=[[0,-.65],[.18,-.19],[.62,-.36],[.33,.03],[.72,.19],[.22,.29],[.32,.69],[0,.39],[-.25,.7],[-.22,.26],[-.7,.35],[-.35,0],[-.7,-.23],[-.19,-.2]];ctx.beginPath();pts.forEach(([x,y],i)=>i?ctx.lineTo(x*r,y*r):ctx.moveTo(x*r,y*r));ctx.closePath();ctx.stroke();}else if(method==="technical"){[-.38,.38].forEach(x=>{ctx.beginPath();ctx.moveTo(x*r,-.6*r);ctx.lineTo(x*r,.6*r);ctx.stroke();});[-.38,.38].forEach(y=>{ctx.beginPath();ctx.moveTo(-.6*r,y*r);ctx.lineTo(.6*r,y*r);ctx.stroke();});ctx.beginPath();ctx.moveTo(-.55*r,-.55*r);ctx.lineTo(.55*r,.55*r);ctx.moveTo(.55*r,-.55*r);ctx.lineTo(-.55*r,.55*r);ctx.stroke();}else{ctx.beginPath();ctx.moveTo(-.65*r,.35*r);ctx.bezierCurveTo(-.2*r,.2*r,.15*r,-.12*r,.35*r,-.62*r);ctx.bezierCurveTo(.38*r,-.05*r,.58*r,.28*r,.75*r,.37*r);ctx.stroke();ctx.beginPath();ctx.moveTo(-.55*r,-.15*r);ctx.bezierCurveTo(-.2*r,-.2*r,.06*r,-.42*r,.18*r,-.62*r);ctx.stroke();}ctx.restore();}
function drawMomentumArenaBeam(x1,y1,x2,y2,width,color,alpha=1){const s=scale();ctx.save();ctx.globalAlpha=alpha;ctx.strokeStyle=color;ctx.lineWidth=Math.max(2,width*s);ctx.lineCap="round";ctx.shadowColor=color;ctx.shadowBlur=8*s;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();ctx.restore();}
function drawMomentumMockup(){const card=currentCard();if(card?.kind!=="momentum"||state.art)return false;const method=String(card.method||"strength").toLowerCase(),meta=MOMENTUM_STUDIO_META[method]||MOMENTUM_STUDIO_META.strength,w=canvas.width,h=canvas.height,s=scale();ctx.save();const bg=ctx.createLinearGradient(0,0,w,h);bg.addColorStop(0,meta.color);bg.addColorStop(.36,meta.color+"d8");bg.addColorStop(.72,"#111824");bg.addColorStop(1,"#05070b");ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);const glow=ctx.createRadialGradient(w*.5,h*.49,0,w*.5,h*.49,w*.62);glow.addColorStop(0,meta.light+"4f");glow.addColorStop(.34,meta.color+"32");glow.addColorStop(1,"rgba(0,0,0,0)");ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);ctx.save();ctx.globalAlpha=.16;ctx.fillStyle="#fff";for(let i=-3;i<8;i++){ctx.beginPath();ctx.moveTo(w*(i*.19),0);ctx.lineTo(w*(i*.19+.14),0);ctx.lineTo(w*(i*.19+.72),h);ctx.lineTo(w*(i*.19+.58),h);ctx.closePath();ctx.fill();}ctx.restore();drawMomentumArenaBeam(-w*.08,h*.31,w*1.08,h*.12,7,meta.light,.42);drawMomentumArenaBeam(-w*.08,h*.58,w*1.08,h*.39,5,meta.light,.24);drawMomentumArenaBeam(-w*.08,h*.78,w*1.08,h*.59,3,meta.light,.16);ctx.strokeStyle="rgba(255,255,255,.30)";ctx.lineWidth=2*s;ctx.beginPath();ctx.arc(w*.5,h*.31,w*.105,0,Math.PI*2);ctx.stroke();ctx.shadowColor=meta.color;ctx.shadowBlur=20*s;drawMomentumGlyph(method,w*.5,h*.31,w*.065);ctx.shadowBlur=0;ctx.textBaseline="middle";ctx.textAlign="left";ctx.fillStyle="#fff";ctx.font=cardFont(META_STACK,18,950);ctx.fillText("WWE LEGACY",w*.075,h*.075);ctx.textAlign="right";ctx.fillStyle="rgba(255,255,255,.82)";ctx.font=cardFont(META_STACK,18,900);ctx.fillText("MOMENTUM",w*.925,h*.075);ctx.textAlign="center";ctx.fillStyle="#fff";ctx.shadowColor=meta.color;ctx.shadowBlur=32*s;ctx.font=cardFont(NUMBER_STACK,154,1000);ctx.fillText(`+${card.amount??1}`,w*.5,h*.535);ctx.shadowBlur=0;ctx.fillStyle="#fff";ctx.font=cardFont(DISPLAY_STACK,56,1000);drawTrackedText(method.toUpperCase(),w*.5,h*.755,2.4*s);ctx.restore();return true;}
function fittedNameFont(text,maxWidth,maxPx,minPx){let px=maxPx;while(px>minPx){ctx.font=cardFont(DISPLAY_STACK,px,900);if(ctx.measureText(text).width<=maxWidth)break;px-=2;}return px;}
function currentSuperstarNameplateStyle(){const card=currentCard();return card?.kind==="superstar"?(STUDIO_SUPERSTAR_NAMEPLATES?.[card.superstarId]||null):null;}
function superstarNameplateFont(style,px){const italic=style?.italic?"italic ":"";return `${italic}1000 ${px*scale()}px ${style?.font||DISPLAY_STACK}`;}
function fittedSuperstarNameFont(text,style,maxWidth,maxPx=78,minPx=28){let px=Math.max(minPx,maxPx*(style?.size||1));const scaleX=Math.max(.68,Math.min(1.12,Number(style?.scaleX)||1));while(px>minPx){ctx.font=superstarNameplateFont(style,px);const tracking=(Number(style?.tracking)||0)*px*scale();if(trackedWidth(text,tracking)*scaleX<=maxWidth)break;px-=1;}return px;}
function drawSuperstarNameText(text,x,y,maxWidth,style){const s=scale(),px=fittedSuperstarNameFont(text,style,maxWidth,78,28),tracking=(Number(style?.tracking)||0)*px*s,scaleX=Math.max(.68,Math.min(1.12,Number(style?.scaleX)||1)),skew=Math.tan((Number(style?.skew)||0)*Math.PI/180);ctx.save();ctx.translate(x,y);ctx.transform(1,0,skew,1,0,0);ctx.scale(scaleX,1);ctx.textAlign="center";ctx.textBaseline="middle";ctx.lineJoin="round";ctx.font=superstarNameplateFont(style,px);ctx.shadowColor=style?.glow||"rgba(255,255,255,.45)";ctx.shadowBlur=10*s;ctx.lineWidth=6.2*s;ctx.strokeStyle=style?.outline||"#07090d";drawTrackedText(text,0,0,tracking,{stroke:true});ctx.shadowBlur=5*s;ctx.lineWidth=2.1*s;ctx.strokeStyle=style?.accent||"#fff";drawTrackedText(text,0,0,tracking,{stroke:true});const fill=ctx.createLinearGradient(0,-px*.55*s,0,px*.48*s);fill.addColorStop(0,style?.top||"#fff");fill.addColorStop(.48,style?.mid||style?.top||"#fff");fill.addColorStop(1,style?.bottom||"#f2c75c");ctx.fillStyle=fill;ctx.shadowColor=style?.glow||"rgba(255,255,255,.45)";ctx.shadowBlur=8*s;drawTrackedText(text,0,0,tracking);ctx.restore();}
function fittedMetaFont(text,maxWidth,maxPx=22,minPx=14){let px=maxPx;while(px>minPx){ctx.font=cardFont(META_STACK,px,700);if(ctx.measureText(text).width<=maxWidth)break;px-=1;}return px;}
function moveRequirementText(card){if(card?.kind!=="move"||card?.finisher)return "";return Object.entries(card.requirements||{}).filter(([,amount])=>Number(amount)>0).map(([method,amount])=>`◆ ${Number(amount)} ${String(method).toUpperCase()}`).join("   •   ");}
function drawRarityStars(){const card=currentCard();if(!card)return;const rarity=Math.max(1,Math.min(4,Number(card.rarity)||1)),w=canvas.width,h=canvas.height,s=scale();ctx.save();ctx.textAlign="center";ctx.textBaseline="middle";ctx.font=`900 ${24*s}px Arial, sans-serif`;ctx.lineJoin="round";for(let i=0;i<rarity;i++){const x=51*s,y=62*s+i*31*s;ctx.lineWidth=3*s;ctx.strokeStyle="rgba(28,18,2,.92)";ctx.shadowColor="rgba(0,0,0,.75)";ctx.shadowBlur=5*s;ctx.strokeText("★",x,y);const gold=ctx.createLinearGradient(x,y-12*s,x,y+12*s);gold.addColorStop(0,"#fff2a6");gold.addColorStop(.46,"#f4c542");gold.addColorStop(1,"#b97608");ctx.fillStyle=gold;ctx.shadowColor="rgba(255,202,55,.48)";ctx.shadowBlur=8*s;ctx.fillText("★",x,y);}ctx.restore();}
function drawMoveStatFigure(cx,label,value){const s=scale(),h=canvas.height;ctx.save();ctx.textAlign="center";ctx.textBaseline="middle";ctx.fillStyle="rgba(255,255,255,.78)";ctx.font=cardFont(META_STACK,17.5,950);drawTrackedText(label,cx,h*.856,1.25*s);ctx.fillStyle="#ffffff";ctx.strokeStyle="#ffffff";ctx.lineJoin="round";ctx.lineWidth=1.35*s;ctx.font=cardFont(NUMBER_STACK,78,1000);ctx.strokeText(String(value),cx,h*.902);ctx.fillText(String(value),cx,h*.902);ctx.restore();}
function drawBottomIdentity(){
  const card=currentCard();if(!card)return;
  const set=currentSet(),w=canvas.width,h=canvas.height,s=scale(),text=card.name.toUpperCase(),isMove=card.kind==="move",isStar=card.kind==="superstar",starStyle=currentSuperstarNameplateStyle();
  const panelTop=isMove?h*.765:isStar?h*.805:h*.81,accent=isStar?(starStyle?.accent||set.border||set.accent):(set.border||set.accent);
  ctx.save();
  const fade=ctx.createLinearGradient(0,h*.56,0,panelTop);fade.addColorStop(0,"rgba(0,0,0,0)");fade.addColorStop(1,isStar?"rgba(0,0,0,.40)":"rgba(0,0,0,.32)");ctx.fillStyle=fade;ctx.fillRect(0,h*.56,w,panelTop-h*.56);
  ctx.beginPath();ctx.moveTo(w*.055,panelTop+11*s);ctx.lineTo(w*.095,panelTop-9*s);ctx.lineTo(w*.905,panelTop-9*s);ctx.lineTo(w*.945,panelTop+11*s);ctx.lineTo(w*.945,h*.974);ctx.lineTo(w*.055,h*.974);ctx.closePath();
  const plate=ctx.createLinearGradient(0,panelTop,0,h);plate.addColorStop(0,isStar?"rgba(18,22,31,.88)":"rgba(14,18,25,.82)");plate.addColorStop(.42,"rgba(6,9,14,.95)");plate.addColorStop(1,"rgba(2,4,8,.99)");ctx.fillStyle=plate;ctx.fill();ctx.strokeStyle=accent;ctx.lineWidth=isStar?3.2*s:2.4*s;ctx.shadowColor=isStar?(starStyle?.glow||set.glow):"transparent";ctx.shadowBlur=isStar?9*s:0;ctx.stroke();ctx.shadowBlur=0;
  ctx.beginPath();ctx.moveTo(w*.095,panelTop-9*s);ctx.lineTo(w*.905,panelTop-9*s);ctx.strokeStyle=accent;ctx.lineWidth=isStar?5.4*s:4*s;ctx.stroke();
  ctx.beginPath();ctx.moveTo(w*.15,panelTop-4*s);ctx.lineTo(w*.85,panelTop-4*s);ctx.strokeStyle="rgba(255,255,255,.58)";ctx.lineWidth=.8*s;ctx.stroke();
  if(isStar){ctx.save();ctx.globalAlpha=.26;ctx.fillStyle=accent;ctx.beginPath();ctx.moveTo(w*.055,h*.90);ctx.lineTo(w*.20,h*.974);ctx.lineTo(w*.055,h*.974);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(w*.945,h*.90);ctx.lineTo(w*.80,h*.974);ctx.lineTo(w*.945,h*.974);ctx.closePath();ctx.fill();ctx.restore();}
  if(state.renderPlateOnly){ctx.restore();return;}
  ctx.textAlign="center";ctx.textBaseline="middle";
  const nameY=isMove?h*.810:isStar?h*.872:h*.875;
  if(isStar){drawSuperstarNameText(text,w*.5,nameY,w*.84,starStyle);}else{fittedNameFont(text,w*.80,isMove?46:50,24);ctx.lineJoin="round";ctx.lineWidth=3.1*s;ctx.strokeStyle="rgba(0,0,0,.94)";ctx.shadowColor="rgba(0,0,0,.72)";ctx.shadowBlur=7*s;ctx.strokeText(text,w*.5,nameY);const ng=ctx.createLinearGradient(0,nameY-24*s,0,nameY+16*s);ng.addColorStop(0,set.nameTop);ng.addColorStop(.66,set.nameTop);ng.addColorStop(1,set.nameBottom);ctx.fillStyle=ng;ctx.shadowColor=set.glow;ctx.shadowBlur=5*s;ctx.fillText(text,w*.5,nameY);ctx.shadowColor="transparent";}
  if(isMove){drawMoveStatFigure(w*.155,"COST",card.cost??0);drawMoveStatFigure(w*.845,"DAMAGE",card.damage??0);const req=moveRequirementText(card);if(req){ctx.fillStyle="rgba(255,255,255,.98)";fittedMetaFont(req,w*.49,26,18);ctx.font=ctx.font.replace(/^\d+ /,'950 ');ctx.fillText(req,w*.5,h*.875);}const moveType=String(card.moveType||card.method||"move").toUpperCase();ctx.fillStyle=set.nameBottom;ctx.font=cardFont(META_STACK,req?18:21,950);drawTrackedText(`MOVE • ${moveType}`,w*.5,req?h*.922:h*.895,1.0*s);}
  else{const type=KIND_LABELS[card.kind]||String(card.kind||"CARD").toUpperCase();ctx.fillStyle=isStar?(starStyle?.accent||set.nameBottom):set.nameBottom;ctx.shadowColor=isStar?(starStyle?.glow||set.glow):"transparent";ctx.shadowBlur=isStar?4*s:0;ctx.font=cardFont(META_STACK,isStar?15:13.5,900);drawTrackedText(type,w*.5,h*.925,isStar?1.25*s:.9*s);ctx.shadowBlur=0;}
  ctx.restore();
}
function drawFrameOverlay(){const set=currentSet();frame(ctx,canvas.width,canvas.height,set.border||set.accent,set.accent2);if(!state.renderPlateOnly)drawRarityStars();}
function drawHeadshot(){const w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);drawArt();}
function draw(){if(isHeadshotMode()){drawHeadshot();return;}if(!state.exportingPlate)state.renderPlateOnly=previewPlateOnly();drawTemplate();const momentumMock=drawMomentumMockup();drawArt();const veil=ctx.createLinearGradient(0,0,0,canvas.height);veil.addColorStop(0,"rgba(0,0,0,.05)");veil.addColorStop(.63,"rgba(0,0,0,0)");veil.addColorStop(1,"rgba(0,0,0,.22)");ctx.fillStyle=veil;ctx.fillRect(0,0,canvas.width,canvas.height);if(!momentumMock){drawSetLogo();drawBottomIdentity();}drawFrameOverlay();}
async function preloadSetLogos(){await Promise.all(Object.keys(SETS).map(async id=>{try{const src=(document.location.protocol==="file:"&&EXPORT_SAFE_SET_LOGOS[id])?EXPORT_SAFE_SET_LOGOS[id]:(SET_LOGO_ASSETS[id]?assetUrl(SET_LOGO_ASSETS[id]):EMBEDDED_SET_LOGOS[id]);if(src)state.setLogos.set(id,await loadImage(src));}catch{}}));draw();}
function setCanvasSize(){const [w,h]=$("#output-size").value.split("x").map(Number);canvas.width=w;canvas.height=h;const wrap=canvas.closest(".canvas-wrap");if(wrap)wrap.style.aspectRatio=`${w} / ${h}`;draw();}
function updateOutputs(){$("#art-zoom-value").textContent=`${Math.round(state.artZoom*100)}%`;$("#art-x-value").textContent=Math.round(state.artX);$("#art-y-value").textContent=Math.round(state.artY);$("#quality-value").textContent=`${$("#quality").value}%`;}
function resetLayout(){state.artZoom=1;state.artX=0;state.artY=0;saveLayout();restoreLayout();draw();}
function updateSummary(){const card=currentCard(),path=destinationFor(card);$("#destination-path").textContent=path;$("#install-path").textContent=isLayeredFormat()?`${path} · OPT-IN LAYERED FRONT`:path;const identity=$("#nameplate-identity");if(!card){if(identity)identity.hidden=true;return;}$("#card-code").textContent=card.cardCode;$("#card-summary-name").textContent=card.name;$("#card-summary-kind").textContent=KIND_LABELS[card.kind]||card.kind.toUpperCase();$("#card-summary-stats").textContent=card.kind==="move"?`COST ${card.cost??0} · DAM ${card.damage??0}${moveRequirementText(card)?` · ${moveRequirementText(card).replaceAll("◆ ","")}`:""}`:card.kind==="momentum"?`+${card.amount??1} ${String(card.method||"").toUpperCase()} MOMENTUM`:"FRONT ART + NAME";$("#preview-card").textContent=`${card.cardCode} · ${card.name}`;$("#preview-label").textContent=currentSet().label;if(identity){const style=currentSuperstarNameplateStyle();identity.hidden=card.kind!=="superstar";if(style){$("#nameplate-style-name").textContent=style.label;$("#nameplate-font-name").textContent=String(style.font||"").split(",")[0].replaceAll('"',"");$("#nameplate-colour-name").textContent=`${style.top} → ${style.mid} → ${style.bottom}`;}}draw();}
function refreshSuperstarFilter(){const set=$("#set-select").value,sel=$("#superstar-select"),previous=sel.value;const stars=STUDIO_SUPERSTARS.filter(s=>set==="all"||s.setId===set);sel.innerHTML=`<option value="all">All Superstars</option>${stars.map(s=>`<option value="${s.id}">${s.name}</option>`).join("")}`;sel.value=stars.some(s=>s.id===previous)?previous:"all";}
function refreshCardList(){const set=$("#set-select").value,kind=$("#type-select").value,star=$("#superstar-select").value,focus=$("#superstar-focus").value,q=$("#card-search").value.trim().toLowerCase(),previous=$("#card-select").value;const cards=STUDIO_CARDS.filter(c=>{if(set!=="all"&&c.setId!==set)return false;if(kind!=="all"&&c.kind!==kind)return false;if(star!=="all"){const ids=focus==="deck"?c.deckSuperstarIds:c.specificSuperstarIds;if(!c.universalSuperstarCard&&!ids?.includes(star))return false;}if(q&&!`${c.name} ${c.cardCode} ${KIND_LABELS[c.kind]||c.kind}`.toLowerCase().includes(q))return false;return true;});const sel=$("#card-select");sel.innerHTML=cards.map(c=>`<option value="${c.id}">${c.cardCode} · ${c.name} · ${KIND_LABELS[c.kind]||c.kind.toUpperCase()}${c.kind==="move"?` · C${c.cost??0}/D${c.damage??0}`:""}</option>`).join("");if(!cards.length){sel.innerHTML='<option value="">No finalized cards yet — template preview</option>';sel.disabled=true;$("#card-code").textContent="FUTURE";$("#card-summary-name").textContent=currentSet().label;$("#card-summary-kind").textContent="SET TEMPLATE";$("#card-summary-stats").textContent="RELEASES 5 SEP 2026";$("#preview-card").textContent=`${currentSet().label} · TEMPLATE PREVIEW`;$("#preview-label").textContent=currentSet().label;draw();return;}sel.disabled=false;sel.value=cards.some(c=>c.id===previous)?previous:cards[0].id;prepareSelectedCard();}
function prepareSelectedCard(){updateSummary();resetLayout();if(document.location.protocol==="file:"){state.art=null;state.artIsProjectAsset=false;resetCanvasSurface();draw();status(currentCard()?.kind==="momentum"?"Built-in Momentum mockup ready — export it as-is or load replacement artwork.":"Choose your artwork with the file picker. Local-file WebP export is ready.",true);return;}if(currentCard()?.kind==="momentum"){state.art=null;state.artIsProjectAsset=false;draw();status("Built-in Momentum mockup ready — export it as-is or load replacement artwork.",true);return;}useCurrentArt();}
async function useCurrentArt(){const card=currentCard();if(!card?.currentArt)return status("No current artwork is available for this card.",false);try{state.art=await loadImage(assetUrl(card.currentArt));state.artIsProjectAsset=true;resetLayout();status(document.location.protocol==="file:"?"Loaded current game art. Choose your own image with the file picker before local-file export.":"Loaded current game art.",true);}catch{status("Could not load the current game artwork.",false);}}
async function fileToImage(file){if(!file)return;status("Reading artwork into export-safe memory…");try{const dataUrl=await readFileAsDataUrl(file);state.art=await loadImage(dataUrl);state.artIsProjectAsset=false;resetCanvasSurface();draw();urlStatus("");status("Artwork loaded. Preview canvas is export-safe.",true);}catch(error){status(`Could not read that image: ${error?.message||error}`,false);}}
async function fetchImageBlob(url,viaProxy=false){
  const source=viaProxy?`https://wsrv.nl/?url=${encodeURIComponent(url.href)}&output=png&maxage=1d`:url.href;
  const response=await fetch(source,{mode:"cors",cache:"no-store",credentials:"omit",referrerPolicy:"no-referrer"});
  if(!response.ok)throw new Error(`${viaProxy?"Image proxy":"Image host"} returned HTTP ${response.status}.`);
  const blob=await response.blob();
  if(blob.type&&!blob.type.toLowerCase().startsWith("image/"))throw new Error(`${viaProxy?"Image proxy":"That URL"} returned ${blob.type||"an unknown file type"}, not an image.`);
  return blob;
}
async function installUrlBlob(blob,viaProxy=false){
  const dataUrl=await readFileAsDataUrl(blob);
  const image=await loadImage(dataUrl);
  state.art=image;state.artIsProjectAsset=false;resetCanvasSurface();resetLayout();
  const message=viaProxy?"URL artwork loaded through the image proxy and is export-safe.":"URL artwork loaded directly and is export-safe.";
  urlStatus(message,true);status(message,true);
}
async function urlToImage(rawUrl){
  const value=String(rawUrl||"").trim();
  if(!value){urlStatus("Paste a direct image URL first.",false);return status("Paste a direct image URL first.",false);}
  let url;
  try{url=new URL(value);if(!/^https?:$/.test(url.protocol))throw new Error("Only http:// and https:// image URLs are supported.");}
  catch(error){const message=`That is not a valid image URL: ${error?.message||error}`;urlStatus(message,false);return status(message,false);}
  const button=$("#load-art-url"),originalLabel=button?.textContent||"Load URL Artwork";
  if(button){button.disabled=true;button.textContent="Loading…";}
  urlStatus("Trying the image URL…");status("Trying the image URL…");
  try{
    try{
      const blob=await fetchImageBlob(url,false);
      await installUrlBlob(blob,false);
    }catch(directError){
      urlStatus("The source blocked direct browser access. Retrying automatically through the image proxy…");
      status("Direct URL access was blocked; retrying through the image proxy…");
      try{
        const blob=await fetchImageBlob(url,true);
        await installUrlBlob(blob,true);
      }catch(proxyError){
        const directText=directError?.message||String(directError),proxyText=proxyError?.message||String(proxyError);
        throw new Error(`Direct load failed (${directText}) and proxy retry failed (${proxyText}).`);
      }
    }
  }catch(error){
    const message=`Could not load URL artwork: ${error?.message||error}`;
    urlStatus(message,false);status(message,false);
  }finally{if(button){button.disabled=false;button.textContent=originalLabel;}}
}
function canvasToBlob(type,quality){return new Promise((resolve,reject)=>{if(typeof canvas.toBlob!=="function")return reject(new Error("This browser does not support canvas export."));try{canvas.toBlob(blob=>blob?resolve(blob):reject(new Error("The browser could not create an image file.")),type,quality);}catch(error){reject(error);}});}
async function encodedCardFile(){const quality=Number($("#quality").value)/100,id=exportId(currentCard());let blob=await canvasToBlob("image/webp",quality);if(blob?.type==="image/webp")return {blob,name:`${id}.webp`,format:"WebP"};blob=await canvasToBlob("image/png");return {blob,name:`${id}.png`,format:"PNG"};}
function renderForExport(){state.exportingPlate=isLayeredFormat();state.renderPlateOnly=state.exportingPlate;draw();}
function restorePreviewAfterExport(){state.exportingPlate=false;state.renderPlateOnly=previewPlateOnly();draw();}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement("a");a.href=u;a.download=name;a.style.display="none";document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),5000);}
async function prepareExport(){const card=currentCard();if(!card)throw new Error("Choose a card before exporting.");if(isHeadshotMode()&&card.kind!=="superstar")throw new Error("HUD Headshot export is available on Superstar cards only.");if(!state.art&&card.kind!=="momentum")throw new Error("Choose or load artwork before exporting.");renderForExport();if(!canvasIsOriginClean()){resetCanvasSurface();renderForExport();}if(!canvasIsOriginClean())throw new Error("This artwork source cannot be exported safely. Re-select only the artwork image with the file picker; all WWE Legacy templates and set logos are now export-safe automatically.");return card;}
async function exportWebp(){try{const card=await prepareExport();status(isLayeredFormat()?"Encoding clean Layered v1 art plate…":"Encoding finished card…");const file=await encodedCardFile();download(file.blob,file.name);const layeredNote=isLayeredFormat()?" Install this plate at the suggested layered path; WWE Legacy will use it automatically and fall back to the existing flat front if it is absent.":"";const note=file.format==="WebP"?`Put it at ${destinationFor(card)}.${layeredNote}`:`PNG fallback saved. Use the Bulk PNG/JPG → WebP Converter before installing it at ${destinationFor(card)}.${layeredNote}`;status(`Saved ${file.name} (${file.format}). ${note}`,true);}catch(error){status(`Export failed: ${error?.message||error}`,false);}finally{restorePreviewAfterExport();}}
async function shareCard(){try{const card=await prepareExport();status(isLayeredFormat()?"Preparing clean Layered v1 art plate for the iPhone share sheet…":"Preparing card for the iPhone share sheet…");const out=await encodedCardFile(),file=new File([out.blob],out.name,{type:out.blob.type});if(navigator.share&&navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:`WWE Legacy — ${card.name}`});status(`Shared ${out.name}. Choose Google Drive or Files in the iOS share sheet.`,true);return;}download(out.blob,out.name);status(`Native file sharing is unavailable here, so ${out.name} was downloaded instead.`,true);}catch(error){if(error?.name==="AbortError")return status("Share cancelled.");status(`Share failed: ${error?.message||error}`,false);}finally{restorePreviewAfterExport();}}
function pointerDistance(){const pts=[...state.pointerMap.values()];return pts.length<2?null:Math.hypot(pts[0].x-pts[1].x,pts[0].y-pts[1].y);}
function onPointerDown(e){if(!state.art)return;canvas.setPointerCapture?.(e.pointerId);state.pointerMap.set(e.pointerId,{x:e.clientX,y:e.clientY});if(state.pointerMap.size===1){state.dragPointerId=e.pointerId;state.dragLast={x:e.clientX,y:e.clientY};}else if(state.pointerMap.size===2){state.lastPinchDistance=pointerDistance();state.dragPointerId=null;state.dragLast=null;}}
function onPointerMove(e){if(!state.pointerMap.has(e.pointerId)||!state.art)return;state.pointerMap.set(e.pointerId,{x:e.clientX,y:e.clientY});const rect=canvas.getBoundingClientRect(),ref=referenceSize(),limits=layoutLimits();if(state.pointerMap.size>=2){const d=pointerDistance();if(d&&state.lastPinchDistance){state.artZoom=Math.max(limits.zoomMin,Math.min(limits.zoomMax,state.artZoom*(d/state.lastPinchDistance)));state.lastPinchDistance=d;syncLayoutControls();saveLayout();updateOutputs();draw();}return;}if(state.dragPointerId===e.pointerId&&state.dragLast){state.artX+=(e.clientX-state.dragLast.x)*(ref.w/rect.width);state.artY+=(e.clientY-state.dragLast.y)*(ref.h/rect.height);state.dragLast={x:e.clientX,y:e.clientY};if(!isHeadshotMode()){state.artX=Math.max(-limits.x,Math.min(limits.x,state.artX));state.artY=Math.max(-limits.y,Math.min(limits.y,state.artY));}syncLayoutControls();saveLayout();updateOutputs();draw();}}
function onPointerUp(e){state.pointerMap.delete(e.pointerId);if(state.pointerMap.size<2)state.lastPinchDistance=null;if(state.pointerMap.size===0){state.dragPointerId=null;state.dragLast=null;}}
function wireCanvasEvents(){canvas.addEventListener("pointerdown",onPointerDown);canvas.addEventListener("pointermove",onPointerMove);canvas.addEventListener("pointerup",onPointerUp);canvas.addEventListener("pointercancel",onPointerUp);canvas.addEventListener("wheel",e=>{if(!state.art)return;e.preventDefault();const limits=layoutLimits();state.artZoom=Math.max(limits.zoomMin,Math.min(limits.zoomMax,state.artZoom*(e.deltaY<0?1.06:.94)));syncLayoutControls();saveLayout();updateOutputs();draw();},{passive:false});}
$("#export-target")?.addEventListener("change",()=>{saveLayout(state.activeLayoutKey);const head=isHeadshotMode(),nextKey=layoutKey();$("#front-workflow")?.classList.toggle("is-disabled",head);if(head){$("#type-select").value="superstar";refreshCardList();$("#output-size").value="1200x400";}else if($("#output-size").value==="1200x400")$("#output-size").value="680x1000";restoreLayout(nextKey);setCanvasSize();updateSummary();status(head?"HUD Headshot mode now supports free artwork panning, a wider zoom range and its own independent 1200 × 400 crop.":"Card Front mode restored. Layered v1 is automatic when its plate exists; otherwise the existing flat front is used.",true);});
$("#front-format")?.addEventListener("change",()=>{const layered=isLayeredFormat();$("#preview-mode").disabled=!layered;$("#export-webp").textContent=layered?"Export Art Plate":"Export Card";$("#share-card").textContent=layered?"Save / Share Art Plate":"Save / Share Card";state.renderPlateOnly=previewPlateOnly();updateSummary();draw();status(layered?"Layered v1 selected. Final Card preview stays complete; exports omit live name, stats, requirements, type and rarity.":"Legacy Flat selected. Export contains the complete finished front exactly as previewed.",true);});
$("#preview-mode")?.addEventListener("change",()=>{state.renderPlateOnly=previewPlateOnly();draw();});
$("#set-select").addEventListener("change",()=>{refreshSuperstarFilter();refreshCardList();});$("#type-select").addEventListener("change",refreshCardList);$("#superstar-select").addEventListener("change",refreshCardList);$("#superstar-focus").addEventListener("change",refreshCardList);$("#card-search").addEventListener("input",refreshCardList);$("#card-select").addEventListener("change",prepareSelectedCard);$("#art-file").addEventListener("change",e=>fileToImage(e.target.files?.[0]));$("#load-art-url").addEventListener("click",()=>urlToImage($("#art-url").value));$("#art-url").addEventListener("keydown",e=>{if(e.key==="Enter"){e.preventDefault();urlToImage(e.currentTarget.value);}});$("#use-current-art").addEventListener("click",useCurrentArt);$("#clear-art").addEventListener("click",()=>{state.art=null;state.artIsProjectAsset=false;draw();urlStatus("");status("Artwork cleared.");});$("#reset-layout").addEventListener("click",resetLayout);$("#output-size").addEventListener("change",setCanvasSize);$("#quality").addEventListener("input",updateOutputs);$("#export-webp").addEventListener("click",exportWebp);$("#share-card")?.addEventListener("click",shareCard);[["#art-zoom",v=>state.artZoom=Number(v)/100],["#art-x",v=>state.artX=Number(v)],["#art-y",v=>state.artY=Number(v)]].forEach(([sel,set])=>$(sel).addEventListener("input",e=>{set(e.target.value);saveLayout();updateOutputs();draw();}));wireCanvasEvents();
try{$("#export-webp").textContent=isLayeredFormat()?"Export Art Plate":"Export Card";$("#share-card").textContent=isLayeredFormat()?"Save / Share Art Plate":"Save / Share Card";refreshSuperstarFilter();refreshCardList();updateOutputs();preloadSetLogos();window.WWE_LEGACY_CARD_ART_STUDIO_READY=true;}catch(error){console.error("Card Art Studio failed to initialise",error);status(`Studio failed to initialise: ${error?.message||error}`,false);}
